def notes_paragraphs(n, deck_page=None, extra_top=None):
    """notes-pane paragraphs for original slide n"""
    d = NOTES[n]
    out = []
    hdr = f"الشريحة {n} في نص العرض الأصلي"
    if deck_page:
        hdr += f" — الصفحة {deck_page} في هذا الملف"
    out.append("## " + hdr)
    if extra_top:
        out.extend(extra_top)
    if "opening" in d:
        out += ["## افتتاحية مقترحة للتقديم", d["opening"],
                "## هدف العرض", d["objective"],
                "## ملاحظة تحريرية (داخلية)", d["editorial"], d["scope"]]
    if "notes" in d:
        out += ["## ملاحظات التقديم", d["notes"]]
    if "status" in d:
        out += ["## حالة المحتوى", d["status"], "## مرجع المحتوى", d["ref"]]
    out += ["## للمراجعة قبل الاجتماع (سجل الإثبات)", d["evidence"]]
    for f in d.get("flags", []):
        out += ["## ⚠ تنبيه من إعداد العرض", f]
    return out
